"""PayPal's official Server SDK (paypal-server-sdk, generated by APIMatic) as PayRecover's
messenger for reading orders, capturing them and refunding captures.

The SDK is synchronous, so app.paypal runs these functions on a worker thread. Each one
returns PayPal's HTTP status and the JSON body PayPal sent, exactly as the REST API returns
it, so every check and leak rule keeps working on the same data. The environment is fixed
to Sandbox here and cannot be configured. Invoicing is not part of the SDK and still goes
through app.paypal.paypal_call.
"""

import hashlib
import json
import threading
from typing import Any

from paypalserversdk.configuration import Environment
from paypalserversdk.exceptions.api_exception import ApiException
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.money import Money
from paypalserversdk.models.refund_request import RefundRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

TIMEOUT_SECONDS = 20
# The SDK keeps its own OAuth token per client, so one client per set of credentials is reused.
_clients: dict[str, PaypalServersdkClient] = {}
_lock = threading.Lock()


def _client(client_id: str, secret: str) -> PaypalServersdkClient:
    key = hashlib.sha256(f"{client_id}:{secret}".encode()).hexdigest()
    with _lock:
        if key not in _clients:
            _clients.clear()
            _clients[key] = PaypalServersdkClient(
                client_credentials_auth_credentials=ClientCredentialsAuthCredentials(
                    o_auth_client_id=client_id, o_auth_client_secret=secret,
                ),
                environment=Environment.SANDBOX,
                timeout=TIMEOUT_SECONDS,
                max_retries=0,
            )
        return _clients[key]


def _json(text: str | None) -> Any:
    try:
        return json.loads(text) if text and text.strip() else None
    except json.JSONDecodeError:
        return None


def _call(action) -> tuple[int, Any]:
    """Run one SDK call; PayPal's error replies come back as (status, body) instead of raising."""
    try:
        response = action()
    except ApiException as exc:
        return exc.response_code, _json(getattr(exc.response, "text", None))
    return response.status_code, _json(response.text)


def get_order(client_id: str, secret: str, order_id: str) -> tuple[int, Any]:
    orders = _client(client_id, secret).orders
    return _call(lambda: orders.get_order({"id": order_id}))


def capture_order(client_id: str, secret: str, order_id: str, request_id: str) -> tuple[int, Any]:
    orders = _client(client_id, secret).orders
    return _call(lambda: orders.capture_order({
        "id": order_id, "paypal_request_id": request_id, "prefer": "return=representation",
    }))


def refund_capture(
    client_id: str, secret: str, capture_id: str, amount: str, currency: str, note: str, request_id: str,
) -> tuple[int, Any]:
    payments = _client(client_id, secret).payments
    body = RefundRequest(amount=Money(currency_code=currency, value=amount), note_to_payer=note)
    return _call(lambda: payments.refund_captured_payment({
        "capture_id": capture_id, "body": body, "paypal_request_id": request_id, "prefer": "return=representation",
    }))


def get_refund(client_id: str, secret: str, refund_id: str) -> tuple[int, Any]:
    payments = _client(client_id, secret).payments
    return _call(lambda: payments.get_refund({"refund_id": refund_id}))
